	void unownedProcessChangingDictionaryAfterPlanningRefusesBeforeRewriteAndReopens(
			@TempDir(cleanup = CleanupMode.NEVER) Path evidence) throws Exception {
		Path referenceDirectory = evidence.resolve("reference");
		Path targetDirectory = evidence.resolve("target");
		createFixture(referenceDirectory);
		createFixture(targetDirectory);
		LmdbStore reference = new LmdbStore(referenceDirectory.toFile(), config());
		List<String> explicit;
		List<String> all;
		try {
			reference.init();
			explicit = statements(reference, false);
			all = statements(reference, true);
			assertTrue(explicit.size() > 1);
		} finally {
			reference.shutDown();
		}
		List<String> before = statementKeys(targetDirectory);
		Files.write(evidence.resolve("statement-keys-before.txt"), before);
		AtomicBoolean entered = new AtomicBoolean();
		AtomicBoolean rewriteStarted = new AtomicBoolean();
		LmdbLanguageTagVariantMerge.stepObserverForTesting = step -> {
			if (step == LmdbLanguageTagVariantMerge.Step.PLANNED && entered.compareAndSet(false, true)) {
				runExternalWriter(targetDirectory, evidence.resolve("foreign-writer.log"), evidence.resolve("child-tmp"));
			} else if (step == LmdbLanguageTagVariantMerge.Step.SKETCH_INVALIDATED) {
				rewriteStarted.set(true);
			}
		};
		AtomicReference<SailException> refused = new AtomicReference<>();
		LmdbStore target = new LmdbStore(targetDirectory.toFile(), config());
		try {
			try {
				target.init();
			} catch (SailException failure) {
				refused.set(failure);
			}
		} finally {
			LmdbLanguageTagVariantMerge.stepObserverForTesting = null;
			target.shutDown();
		}
		List<String> after = statementKeys(targetDirectory);
		Files.write(evidence.resolve("statement-keys-after.txt"), after);
		assertTrue(entered.get(), "the independent writer must run after the real plan");
		assertFalse(rewriteStarted.get(), "an unowned generation must be rejected before rewrite bookkeeping");
		assertEquals(before, after, "no statement key may change after the stale plan");
		assertTrue(refused.get() != null, "the stale plan must refuse initialization");

		LmdbStore reopened = new LmdbStore(targetDirectory.toFile(), config());
		try {
			reopened.init();
			assertEquals(explicit, statements(reopened, false));
			assertEquals(all, statements(reopened, true));
			ValueStore values = (ValueStore) reopened.getValueFactory();
			var vf = SimpleValueFactory.getInstance();
			assertTrue(values.getId(vf.createIRI("urn:external-migration-writer")) > 0L,
					"the unowned writer's valid independent owner must remain present");
			long lower = values.getId(vf.createLiteral("language value", "en"));
			assertTrue(lower > 0L);
			assertEquals(lower, values.getId(vf.createLiteral("language value", "eN")),
					"reopen must replan the newly introduced language alias");
		} finally {
			reopened.shutDown();
		}
	}

