	private static boolean inLosingLiteralRetirement() {
		for (StackTraceElement frame : Thread.currentThread().getStackTrace()) {
			if (frame.getClassName().equals(ValueStore.class.getName())
					&& frame.getMethodName().equals("retireLosingLiterals")) {
				return true;
			}
		}
		return false;
	}

	private static void runExternalWriter(Path directory, Path log, Path temporaryDirectory) throws IOException {
		Files.createDirectories(temporaryDirectory);
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		Process child = new ProcessBuilder(java, "--enable-native-access=ALL-UNNAMED", "-ea",
				"-Djava.io.tmpdir=" + temporaryDirectory, "-cp", System.getProperty("java.class.path"),
				ExternalWriter.class.getName(), directory.toString()).redirectErrorStream(true)
						.redirectOutput(log.toFile()).start();
		try {
			if (!child.waitFor(30, TimeUnit.SECONDS)) {
				child.destroyForcibly();
				throw new IOException("independent native writer did not finish: " + log);
			}
			String output = Files.readString(log);
			if (child.exitValue() != 0 || !output.contains("EXTERNAL_OWNER_COMMITTED")) {
				throw new IOException("independent native writer failed: " + output);
			}
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			child.destroyForcibly();
			throw new IOException("interrupted while awaiting the independent native writer", interrupted);
		}
	}

	public static final class ExternalWriter {
		public static void main(String[] args) throws Exception {
			Path directory = Path.of(args[0]);
			StoreProperties properties = new StoreProperties(directory.toFile());
			if (!properties.load()) {
				throw new IOException("missing test fixture properties");
			}
			LmdbStoreConfig config = config();
			ValueStore values = new ValueStore(directory.resolve("values").toFile(), properties, config, false,
					null, LmdbStoreFormat.fromProperties(properties, config), true);
			try {
				long before = values.lastTransactionId();
				var vf = SimpleValueFactory.getInstance();
				values.startTransaction(false);
				long owner = values.getId(vf.createIRI("urn:external-migration-writer"), true);
				long lower = values.getId(vf.createLiteral("language value", "en"), false);
				values.clearCaches();
				long alias = values.getId(vf.createLiteral("language value", "eN"), true);
				if (owner <= 0L || lower <= 0L || alias == lower) {
					throw new IOException("the independent writer did not add the intended owners");
				}
				values.commit();
				if (values.lastTransactionId() <= before) {
					throw new IOException("the independent native generation did not advance");
				}
				System.out.println("EXTERNAL_OWNER_COMMITTED");
			} finally {
				values.close();
			}
		}
	}

