	private static List<String> statementKeys(Path directory) throws IOException {
		long environment = NULL;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
			E(mdb_env_set_maxdbs(environment, 128));
			E(mdb_env_open(environment, directory.resolve("triples").toString(), MDB_NOTLS | MDB_RDONLY, 0664));
			return LmdbUtil.readTransaction(environment, (inner, txn) -> {
				var db = inner.mallocInt(1);
				E(mdb_dbi_open(txn, TripleIndex.nativeDatabaseName("spoc", true), 0, db));
				PointerBuffer cursor = inner.mallocPointer(1);
				E(mdb_cursor_open(txn, db.get(0), cursor));
				try {
					List<String> keys = new ArrayList<>();
					MDBVal key = MDBVal.calloc(inner);
					MDBVal value = MDBVal.calloc(inner);
					int rc = mdb_cursor_get(cursor.get(0), key, value, MDB_FIRST);
					while (rc == MDB_SUCCESS) {
						ByteBuffer bytes = key.mv_data().duplicate();
						byte[] encoded = new byte[bytes.remaining()];
						bytes.get(encoded);
						keys.add(HexFormat.of().formatHex(encoded));
						rc = mdb_cursor_get(cursor.get(0), key, value, MDB_NEXT);
					}
					if (rc != MDB_NOTFOUND) {
						E(rc);
					}
					return List.copyOf(keys);
				} finally {
					mdb_cursor_close(cursor.get(0));
				}
			});
		} finally {
			if (environment != NULL) {
				mdb_env_close(environment);
			}
		}
	}

	private static List<String> statements(LmdbStore store, boolean includeInferred) {
		List<String> rows = new ArrayList<>();
		try (SailConnection connection = store.getConnection();
				var statements = connection.getStatements(null, null, null, includeInferred)) {
			while (statements.hasNext()) {
				Statement statement = statements.next();
				rows.add(NTriplesUtil.toNTriplesString(statement.getSubject()) + " "
						+ NTriplesUtil.toNTriplesString(statement.getPredicate()) + " "
						+ NTriplesUtil.toNTriplesString(statement.getObject())
						+ (statement.getContext() == null ? "" : " "
								+ NTriplesUtil.toNTriplesString(statement.getContext())));
			}
		}
		Collections.sort(rows);
		return rows;
	}
